import { $, i, icons, busy, reportError, toast, badge, closeModal, modal } from './ui.js';
import { listPolicies, expenseDetails, saveExpense, receiptURL, rpc } from './api.js';
import { categories, escapeHTML as h, INR, today, dateLabel, timeLabel, shortID, statuses } from './utils.js';
import { extractReceipt } from './ocr.js';
import { ticketPanel, bindTicketPanel } from './tickets.js';
import { awaitingManagerAssignment } from './expense-state.js';
export async function submitExpense(profile) {
  if(profile.role!=='employee')throw new Error('Only employee accounts can file or edit expenses.');
  const params=new URLSearchParams(location.search),draftID=params.get('id'),requestID=params.get('request');let draft=null;
  if(draftID||requestID){draft=await expenseDetails(draftID||requestID,{optional:!draftID});if(draft&&draft.employee_id!==profile.id)throw new Error('Only your own drafts can be edited.');if(draft&&draft.status!=='draft'){location.replace('expense-details.html?id='+encodeURIComponent(draft.id));return;}}
  const policies=await listPolicies(),id=draft?.id||requestID||crypto.randomUUID();
  // Keep the operation ID through a lost response or page refresh; never create a second claim on retry.
  if(!draftID)history.replaceState(null,'','submit-expense.html?request='+encodeURIComponent(id));
  $('#page-content').innerHTML=`<div class="submission-layout"><section class="panel"><div class="panel-header"><div><h2>${draft?'Edit your draft':'Expense details'}</h2><p>Your claim is verified on the server when submitted</p></div></div><form id="expense-form"><div class="modal-body"><div class="form-grid"><div class="field full"><label for="title">Expense title *</label><input name="title" id="title" required maxlength="120" placeholder="Bengaluru business trip" value="${h(draft?.title||'')}"></div><div class="field"><label for="employee-name">Employee name</label><input id="employee-name" readonly value="${h(profile.full_name)}"></div><div class="field"><label for="employee-id">Employee ID</label><input id="employee-id" readonly value="${h(profile.employee_code||profile.id)}"></div><div class="field"><label for="category">Category *</label><select name="category" id="category" required><option value="">Select category</option>${categories.map(c=>`<option ${draft?.category===c?'selected':''}>${c}</option>`).join('')}</select><small id="limit-hint">Select a category to view its limit.</small></div><div class="field"><label for="amount">Amount in INR (₹) *</label><input name="amount" id="amount" type="number" min="0.01" max="10000000" step="0.01" required placeholder="2000" value="${h(draft?.amount||'')}"></div><div class="field"><label for="expense-date">Expense date *</label><input name="expense_date" id="expense-date" type="date" required max="${today()}" value="${h(draft?.expense_date||today())}"></div><div class="field"><label for="merchant">Merchant / vendor *</label><input name="merchant" id="merchant" required maxlength="120" placeholder="IndiGo" value="${h(draft?.merchant||'')}"></div><div class="field full"><label for="invoice">Invoice number (optional)</label><input name="invoice_number" id="invoice" maxlength="80" placeholder="INV-2026-104" value="${h(draft?.invoice_number||'')}"><small>Used as an additional duplicate-check signal.</small></div><div class="field full form-section"><h3>Purchase transaction</h3><p class="muted-note">Enter how you paid the merchant. Reimbursement bank details will be requested after approval.</p></div><div class="field"><label for="payment-method">Payment method (required to submit)</label><select name="payment_method" id="payment-method"><option value="">Select payment method</option>${['UPI','Debit Card','Credit Card','Bank Transfer','Cash','Other'].map(method=>`<option ${draft?.payment_method===method?'selected':''}>${method}</option>`).join('')}</select></div><div class="field"><label for="transaction-date">Payment date (required to submit)</label><input name="transaction_date" id="transaction-date" type="date" max="${today()}" value="${h(draft?.transaction_date||'')}"></div><div class="field full"><label for="purchase-reference">Transaction / UTR reference</label><input name="purchase_reference" id="purchase-reference" maxlength="120" value="${h(draft?.purchase_reference||'')}" placeholder="UPI, bank or card payment reference"><small id="purchase-reference-hint">Required for non-cash payments. Enter a reference, never your card number, PIN or OTP.</small></div><div class="field full"><label for="purpose">Business purpose (required to submit)</label><textarea name="purpose" id="purpose" maxlength="1000" placeholder="Travel for the Bengaluru client meeting.">${h(draft?.purpose||'')}</textarea></div><div class="field full"><label for="description">Description</label><textarea name="description" id="description" maxlength="2000" placeholder="Any extra details for your reviewer…">${h(draft?.description||'')}</textarea></div><div class="field full"><label for="receipt">Proof of purchase — receipt / invoice (required to submit)</label><div class="upload-zone">${i('cloud-upload')}<strong>Attach your purchase receipt or invoice</strong><small>JPG, PNG or PDF · Maximum 5 MB · Private storage</small><input id="receipt" type="file" accept="image/jpeg,image/png,application/pdf"><div id="file-label" class="selected-file">${h(draft?.receipt_name||'')}</div></div><div id="file-preview"></div><button id="ocr-button" class="button secondary" type="button" disabled>${i('scan-text')}Extract receipt details</button><small id="ocr-message">Optional image OCR. You can always enter or correct details manually.</small></div><div class="field full"><label for="payment-proof">Payment proof (optional)</label><div class="upload-zone">${i('image-plus')}<strong>Attach a transaction screenshot or payment receipt</strong><small>JPG, PNG or PDF · Maximum 5 MB · Private storage</small><input id="payment-proof" type="file" accept="image/jpeg,image/png,application/pdf"><div id="payment-proof-label" class="selected-file">${h(draft?.payment_proof_name||'')}</div></div><div id="payment-proof-preview"></div><small>Show the payment reference, date and amount. Crop unrelated transactions and balances.</small></div></div><div id="form-result" class="form-feedback" hidden role="status"></div></div><div class="modal-footer"><a class="button secondary" href="my-expenses.html">Cancel</a><button class="button secondary" id="save-draft" type="button">${i('save')}Save draft</button><button class="button primary" id="submit-claim" type="submit">Submit expense ${i('arrow-right')}</button></div></form></section><aside><section class="panel submission-help"><span class="stat-icon lavender">${i('shield-check')}</span><h3>Checked before approval.</h3><p>We check your amount, date, receipt fingerprint and company policy. Potential duplicates are flagged for review.</p><div class="help-line">${i('check')}Policy limit verification</div><div class="help-line">${i('check')}Server-calculated receipt hash</div><div class="help-line">${i('check')}Assigned manager review</div><div class="help-line">${i('check')}A complete audit timeline</div><p class="muted-note">OCR and automated rules do not prove authenticity. Your manager reviews the original receipt.</p></section>${!profile.manager_id?`<div class="notice" style="margin-top:18px">${i('info')}<div>No manager is assigned yet. You can submit your expense now. It will remain pending review until an administrator assigns a manager.</div></div>`:''}<section class="panel submission-help scenario-card"><div class="eyebrow">DEMONSTRATION SCENARIO</div><h3>Bengaluru business trip</h3><p>Submit these as three separate claims with the sample PNG receipts.</p><div class="scenario-row"><span>Travel</span><b>₹2,000</b></div><div class="scenario-row"><span>Hotel</span><b>₹1,500</b></div><div class="scenario-row"><span>Food</span><b>₹500</b></div></section></aside></div>`;
  let file=null,previewURL=null,paymentProof=null,paymentPreviewURL=null,saving=false;
  const feedback=text=>{const el=$('#form-result');el.hidden=false;el.textContent=text;};
  $('#category').onchange=()=>{const p=policies.find(p=>p.category===$('#category').value);$('#limit-hint').textContent=p?`Policy limit: ${INR(p.maximum_amount)} per claim${p.active?'':' · Requires manual review (inactive)'}`:'Select a category to view its limit.';};$('#category').onchange();
  $('#receipt').onchange=e=>{file=e.target.files[0]||null;if(previewURL)URL.revokeObjectURL(previewURL);$('#file-preview').innerHTML='';$('#ocr-button').disabled=true;if(!file)return;if(!['image/jpeg','image/png','application/pdf'].includes(file.type)||file.size>5*1024*1024||file.size===0){file=null;e.target.value='';$('#file-label').textContent='';feedback('Choose a non-empty JPG, PNG or PDF file smaller than 5 MB.');return;}$('#file-label').textContent=`${file.name} · ${(file.size/1024).toFixed(0)} KB`;previewURL=URL.createObjectURL(file);if(file.type.startsWith('image/')){$('#file-preview').innerHTML=`<img class="receipt-preview" alt="Selected receipt preview" src="${previewURL}">`;$('#ocr-button').disabled=false;}else{$('#ocr-message').textContent='PDF uploaded. Enter its details manually; image OCR is unavailable for PDF receipts.';}};
  $('#payment-method').onchange=()=>{$('#purchase-reference-hint').textContent=$('#payment-method').value==='Cash'?'Cash payments do not require a transaction reference. A purchase receipt is still required.':'Required for non-cash payments. Enter a reference, never your card number, PIN or OTP.';};
  $('#payment-method').onchange();
  $('#payment-proof').onchange=evt=>{paymentProof=evt.target.files[0]||null;if(paymentPreviewURL)URL.revokeObjectURL(paymentPreviewURL);$('#payment-proof-preview').replaceChildren();$('#payment-proof-label').textContent=draft?.payment_proof_name||'';if(!paymentProof)return;if(!['image/jpeg','image/png','application/pdf'].includes(paymentProof.type)||paymentProof.size>5*1024*1024||paymentProof.size===0){paymentProof=null;evt.target.value='';feedback('Payment proof must be a non-empty JPG, PNG or PDF smaller than 5 MB.');return;}$('#payment-proof-label').textContent=paymentProof.name;if(paymentProof.type.startsWith('image/')){paymentPreviewURL=URL.createObjectURL(paymentProof);const img=document.createElement('img');img.src=paymentPreviewURL;img.alt='Selected payment proof';img.className='receipt-preview';$('#payment-proof-preview').appendChild(img);}};
  $('#ocr-button').onclick=e=>busy(e.currentTarget,async()=>{if(!file)return;$('#ocr-message').textContent='Loading OCR. This can take a moment…';try{const result=await extractReceipt(file,p=>$('#ocr-message').textContent=`Reading receipt… ${p}%`);if(result.merchant&&!$('#merchant').value)$('#merchant').value=result.merchant;if(result.amount&&!$('#amount').value)$('#amount').value=result.amount;if(result.date)$('#expense-date').value=result.date;$('#ocr-message').textContent='OCR completed. Check the merchant, date and total carefully and correct any mistakes.';toast('Receipt text extracted. Review all suggested values.');}catch(e){$('#ocr-message').textContent='OCR unavailable. Enter the bill details manually.';reportError(e);}});
  async function save(action,button) {
    if(saving)return;
    button=button||$('#submit-claim');
    $('#payment-method').required=action==='submit';$('#transaction-date').required=action==='submit';$('#purchase-reference').required=action==='submit'&&$('#payment-method').value!=='Cash';$('#purchase-reference').minLength=$('#purchase-reference').required?3:0;
    $('#purpose').required=action==='submit';$('#purpose').minLength=action==='submit'?8:0;if(!$('#expense-form').reportValidity()){feedback('Missing Information: complete the highlighted required fields.');return;}
    if(action==='submit'&&!file&&!draft?.receipt_path){feedback('Attach a receipt before submitting.');return;}
    const payload=Object.fromEntries(new FormData($('#expense-form')));payload.amount=Number(payload.amount);
    saving=true;await busy(button,async()=>{const other=action==='draft'?$('#submit-claim'):$('#save-draft');other.disabled=true;try{const saved=await saveExpense(payload,file,action,id,paymentProof);location.assign('expense-details.html?id='+encodeURIComponent(saved));}finally{other.disabled=false;saving=false;}});
  }
  $('#save-draft').onclick=e=>save('draft',e.currentTarget);$('#expense-form').onsubmit=e=>{e.preventDefault();save('submit',e.submitter);};window.addEventListener('pagehide',()=>{if(previewURL)URL.revokeObjectURL(previewURL);if(paymentPreviewURL)URL.revokeObjectURL(paymentPreviewURL);},{once:true});icons();
}
export async function detailsPage(profile) {
  const id=new URLSearchParams(location.search).get('id');if(!id)throw new Error('Choose an expense from your dashboard first.');const e=await expenseDetails(id);const ticket=e.ticket;
  const mayReview=profile.role==='manager'&&e.assigned_manager_id===profile.id&&e.employee_id!==profile.id&&['pending','flagged'].includes(e.status);
  const mayProcess=profile.role==='finance'&&['approved','processing'].includes(e.status),payment=e.reimbursements[0];
  const flow=['draft','pending','approved','processing','paid'];let current=flow.indexOf(e.status);if(e.status==='flagged')current=1;
  $('#page-content').innerHTML=`${awaitingManagerAssignment(e)?`<div class="notice section-space" role="status">${i('info')}<div><strong>Expense saved — awaiting manager assignment.</strong> Your submission and receipt are stored securely. An administrator must assign a manager before it can be reviewed. You do not need to submit it again.</div></div>`:''}<div class="details-layout"><section class="panel"><div class="panel-header"><div><h2>${h(e.title)}</h2><p>${shortID(e.id)} · ${h(e.employee_name)} · ${h(e.department)}</p></div>${badge(e.status)}</div><div class="modal-body"><div class="detail-hero"><div class="detail-amount">${INR(e.amount)}</div><span class="category-pill">${h(e.category)}</span></div><div class="status-timeline">${[['draft','Draft'],['pending','Review'],['approved','Approved'],['processing','Processing'],['paid','Reimbursed']].map(([s,label],n)=>`<div class="timeline-step ${n<=current?'complete':''} ${e.status==='rejected'?'declined':''}"><span>${n<=current?i('check'):n+1}</span><small>${label}</small></div>`).join('')}</div>${e.status==='rejected'?'<div class="form-feedback">The manager rejected this request. See the reason below.</div>':''}<div class="detail-grid"><div><small>Merchant</small><strong>${h(e.merchant)}</strong></div><div><small>Expense date</small><strong>${dateLabel(e.expense_date)}</strong></div><div><small>Invoice number</small><strong>${h(e.invoice_number||'Not provided')}</strong></div><div><small>Submitted</small><strong>${timeLabel(e.created_at)}</strong></div><div><small>Purchase payment method</small><strong>${h(e.payment_method||'Not recorded on this older claim')}</strong></div><div><small>Purchase payment date</small><strong>${e.transaction_date?dateLabel(e.transaction_date):'Not recorded'}</strong></div><div class="full"><small>Purchase transaction / UTR reference</small><strong>${h(e.purchase_reference||(e.payment_method==='Cash'?'Cash payment':'Not recorded'))}</strong></div><div class="full"><small>Business purpose</small><strong>${h(e.purpose||'Draft: not entered yet')}</strong></div>${e.description?`<div class="full"><small>Description</small><strong>${h(e.description)}</strong></div>`:''}</div><div class="receipt-actions"><div>${i('receipt')} ${h(e.receipt_name||'No receipt uploaded')}<small>Private receipt · Access expires after 2 minutes</small></div>${e.receipt_path?'<button class="button secondary" id="view-receipt">View purchase proof</button>':''}</div><div id="receipt-container"></div>${e.payment_proof_path?`<div class="receipt-actions"><div>${i('credit-card')} ${h(e.payment_proof_name)}<small>Private payment proof</small></div><button class="button secondary" id="view-payment-proof">View payment proof</button></div><div id="payment-proof-container"></div>`:''}<h3 class="section-label">VERIFICATION SUMMARY</h3><div class="verification-summary ${e.verification_status==='Policy Compliant'?'compliant':'warning'}">${i(e.verification_status==='Policy Compliant'?'shield-check':'flag')}<div><strong>${h(e.verification_status)}</strong><p>${e.status==='draft'?'Verification runs when you submit your draft.':'Required fields, amount, date and receipt were checked on the server.'}</p></div></div>${e.verification_details.map(f=>`<div class="check-line fail">${i('triangle-alert')}<div><strong>${h(f.label)}</strong><p>${h(f.reason)}</p></div></div>`).join('')}<p class="muted-note">Automatic checks identify policy issues and possible duplicates. They do not declare a claim fraudulent or prove receipt authenticity.</p>${e.approvals.map(a=>`<div class="review-comment"><strong>Manager ${h(a.decision)}</strong><p>${h(a.comments||'No additional comment.')}</p><small>${timeLabel(a.decision_date)}</small></div>`).join('')}${payment?`<div class="review-comment"><strong>Reimbursement: ${h(payment.status)}</strong><p>${payment.transaction_reference?'Demo reference: '+h(payment.transaction_reference):'Finance processing started.'}</p><small>${payment.payment_date?'Recorded payment date: '+dateLabel(payment.payment_date):''} · No money was transferred</small></div>`:''}</div></section><aside>${ticketPanel(ticket,profile,e)}<section class="panel"><div class="panel-header"><div><h2>Claim activity</h2><p>Database-recorded audit trail</p></div></div><div class="modal-body">${e.logs.map(log=>`<div class="history-line">${h(log.action)}${log.metadata.comments?`<p>${h(log.metadata.comments)}</p>`:''}<small>${timeLabel(log.created_at)}</small></div>`).join('')}</div></section>${profile.role==='employee'&&e.status==='draft'&&e.employee_id===profile.id?`<a class="button primary detail-action" href="submit-expense.html?id=${encodeURIComponent(e.id)}">${i('pencil')}Edit draft</a>`:''}${mayReview?`<section class="panel review-box"><h3>Manager decision</h3><p class="muted-note">Review the original receipt. A comment of at least 8 characters is required for rejection or a policy exception.</p><label class="field"><span>Approval comment / rejection reason</span><textarea id="review-comments" maxlength="1000" placeholder="Document your decision…"></textarea></label><div class="review-buttons"><button class="button danger" id="reject-expense">Reject</button><button class="button primary" id="approve-expense">${i('check')}Approve</button></div></section>`:''}${mayProcess?`<section class="panel review-box"><h3>Finance processing</h3><p class="muted-note">Record a simulated reimbursement. No actual bank transfer takes place.</p>${e.status==='approved'?`${ticket?.status!=='submitted'?'<p class="muted-note">The employee must submit bank details through their ticket before processing.</p>':''}<button class="button primary" id="start-processing" ${ticket?.status!=='submitted'?'disabled':''}>${i('clock-3')}Start processing</button>`:`<form id="payment-form"><div class="field"><label for="transaction-reference">Demo transaction reference</label><input id="transaction-reference" required minlength="3" maxlength="120" placeholder="DEMO-2026-001"></div><div class="field" style="margin-top:12px"><label for="payment-date">Recorded payment date</label><input id="payment-date" type="date" required min="${e.expense_date}" max="${today()}" value="${today()}"></div><button class="button primary detail-action" type="submit" ${ticket?.status!=='submitted'?'disabled':''}>${i('wallet')}Mark reimbursed (demo)</button></form>`}</section>`:''}</aside></div>`;
  if($('#view-receipt'))$('#view-receipt').onclick=buttonEvent=>busy(buttonEvent.currentTarget,async()=>{const url=await receiptURL(e.receipt_path);const box=$('#receipt-container');box.replaceChildren();if(e.receipt_type?.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt='Uploaded receipt for '+e.title;img.className='receipt-preview';box.appendChild(img);}const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.className='text-button';a.textContent='Open receipt in a new tab (link valid for 2 minutes)';box.appendChild(a);});
  bindTicketPanel(ticket,profile,e,()=>reloadSaved('Bank details submitted securely. Finance has been notified.'));
  if($('#view-payment-proof'))$('#view-payment-proof').onclick=evt=>busy(evt.currentTarget,async()=>{const url=await receiptURL(e.payment_proof_path),box=$('#payment-proof-container');box.replaceChildren();if(e.payment_proof_type?.startsWith('image/')){const img=document.createElement('img');img.src=url;img.alt='Purchase payment proof';img.className='receipt-preview';box.appendChild(img);}const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener noreferrer';a.className='text-button';a.textContent='Open payment proof (link valid for 2 minutes)';box.appendChild(a);});
  if(location.hash==='#bank-ticket')$('#bank-ticket')?.scrollIntoView({block:'start'});
  async function reloadSaved(message){try{await detailsPage(profile);toast(message);return true;}catch(error){toast(message+' Reload this page to retrieve the latest saved status.','error');return false;}}
  async function review(decision,button) {const comments=$('#review-comments').value.trim();if((decision==='rejected'||e.status==='flagged')&&comments.length<8){toast('Enter a reason of at least 8 characters.','error');$('#review-comments').focus();return;}modal(`Confirm ${decision==='approved'?'approval':'rejection'}`,`<p class="muted-note">${h(e.title)} · ${INR(e.amount)}<br>This decision will be recorded in the audit trail.</p>`,`<button class="button secondary" data-modal-close>Cancel</button><button class="button ${decision==='approved'?'primary':'danger'}" id="confirm-review">Confirm ${decision==='approved'?'approval':'rejection'}</button>`);$('#confirm-review').onclick=x=>busy(x.currentTarget,async()=>{await rpc('review_expense',{p_id:e.id,p_decision:decision,p_comments:comments});closeModal();await reloadSaved('Manager decision saved. Employee notified.');});}
  if($('#approve-expense'))$('#approve-expense').onclick=x=>review('approved',x.currentTarget);if($('#reject-expense'))$('#reject-expense').onclick=x=>review('rejected',x.currentTarget);
  if($('#start-processing'))$('#start-processing').onclick=x=>busy(x.currentTarget,async()=>{await rpc('process_reimbursement',{p_id:e.id,p_action:'processing'});await reloadSaved('Demo reimbursement processing started.');});
  if($('#payment-form'))$('#payment-form').onsubmit=x=>{x.preventDefault();const reference=$('#transaction-reference').value.trim(),date=$('#payment-date').value;modal('Record demo reimbursement?',`<p class="muted-note">${h(e.title)} · ${INR(e.amount)}<br>Reference: ${h(reference)}<br>No money will be transferred.</p>`,`<button class="button secondary" data-modal-close>Cancel</button><button class="button primary" id="confirm-payment">Record reimbursement</button>`);$('#confirm-payment').onclick=evt=>busy(evt.currentTarget,async()=>{await rpc('process_reimbursement',{p_id:e.id,p_action:'paid',p_reference:reference,p_payment_date:date});closeModal();await reloadSaved('Demo reimbursement completed and recorded.');});};icons();
}
